  return { months, undated };
}
<script lang="ts">
  import { page } from "$app/state";
  import { formatPounds } from "./lib/member-summary";
  import Icon from "./lib/Icon.svelte";
  import { memberHref, type MemberProfile } from "./lib/entity-details";
  let {
    member,
    view,
    total,
  }: {
    member: MemberProfile;
    view: "summary" | "history";
    total: string | null;
  } = $props();
</script>

<header class="member-identity">
  <div class="member-identity-info">
    <div class="member-identity-title">
      <span class="profile-type"><Icon name="parliament" size={20} />MP</span>
      <h1>{member.name}</h1>
    </div>
    <p>
      {member.partyName || "Party unavailable"}<span
        >{member.membershipFrom || "Membership unavailable"}</span
      ><span>{member.isCurrentCommons ? "Current MP" : "Former MP"}</span>
    </p>
  </div>
  {#if view === "summary"}<div class="member-value">
      <span>Known declared value</span>
      <p class="member-total">{formatPounds(total)}</p>
    </div>{/if}
  <nav class="member-tabs" aria-label="Member views">
    <a
      href={memberHref(member.id, "summary", page.url.searchParams)}
      aria-current={view === "summary" ? "page" : undefined}>Summary</a
    >
    <a
      href={memberHref(member.id, "history", page.url.searchParams)}
      aria-current={view === "history" ? "page" : undefined}
      >Declaration history</a
    >
  </nav>
</header>
<script lang="ts">
  import { page } from "$app/state";
  import MemberDeclarations from "./MemberDeclarations.svelte";
  import RegistrationTimeline from "./RegistrationTimeline.svelte";
  import {
    categoryBars,
    memberHref,
    type MemberDetails,
  } from "./lib/entity-details";
  import { formatPounds, summarizeMember } from "./lib/member-summary";
  let {
    details,
    summary,
  }: { details: MemberDetails; summary: ReturnType<typeof summarizeMember> } =
    $props();
  const bars = $derived(categoryBars(summary.categories, "total"));
  const baseline = $derived(
    bars.reduce((total, bar) => total + (bar.negative ? bar.width : 0), 0),
  );
</script>

<div class="member-summary-top">
  <section class="member-breakdown" aria-labelledby="breakdown-heading">
    <h2 id="breakdown-heading">Declared value by category</h2>
    {#if summary.categories.length}
      <ul class="category-list" style:--baseline={`${baseline}%`}>
        {#each summary.categories as category, index}
          <li>
            <div class="category-label">
              <span>{category.categoryName}</span><span class="amount"
                >{formatPounds(category.amount)}</span
              >
            </div>
            <div class="signed-bar" aria-hidden="true">
              <span
                class:negative={bars[index].negative}
                style:width={`${bars[index].width}%`}
              ></span>
            </div>
            {#if category.unknownAmountCount}<p class="partial-note">
                Some amounts unavailable
              </p>{/if}
          </li>
        {/each}
      </ul>
    {:else}<p class="empty-details">No known declared values available.</p>{/if}
  </section>
  <RegistrationTimeline
    context="earnings"
    months={summary.earnings}
    undated={summary.undated}
  />
</div>
<section aria-labelledby="recent-declarations-heading">
  <div class="detail-section-heading">
    <h2 id="recent-declarations-heading">Recent declarations</h2>
  </div>
  {#if details.declarations.length}<MemberDeclarations
      declarations={details.declarations.slice(0, 5)}
    />{:else}<p class="empty-details">
      No declarations are stored for this MP.
    </p>{/if}
  <a
    class="text-button history-link"
    href={memberHref(details.member.id, "history", page.url.searchParams)}
    >View declaration history</a
  >
</section>
<script lang="ts">
  import MemberDeclarations from "./MemberDeclarations.svelte";
  import { type MemberDetails } from "./lib/entity-details";
  let { details }: { details: MemberDetails } = $props();
  let from = $state("");
  let to = $state("");
  let page = $state(1);
  const pageSize = 10;
  const reversed = $derived(from !== "" && to !== "" && from > to);
  const filtered = $derived(
    reversed
      ? []
      : details.declarations.filter((declaration) => {
          if (!from && !to) return true;
          if (declaration.registeredAt === null) return false;
          const day = new Date(declaration.registeredAt)
            .toISOString()
            .slice(0, 10);
          return (!from || day >= from) && (!to || day <= to);
        }),
  );
  const pageCount = $derived(
    Math.max(1, Math.ceil(filtered.length / pageSize)),
  );
  const visible = $derived(
    filtered.slice((page - 1) * pageSize, page * pageSize),
  );
  function resetPage() {
    page = 1;
  }
  function clearDates() {
    from = "";
    to = "";
    resetPage();
  }
</script>

<section aria-labelledby="history-heading">
  <div class="detail-section-heading">
    <h2 id="history-heading">Declaration history</h2>
    <p>
      All {details.declarations.length} stored declarations, most recent registration
      first.
    </p>
  </div>
  <div class="history-filters">
    <label
      >Registered from<input
        type="date"
        bind:value={from}
        onchange={resetPage}
      /></label
    ><label
      >Registered to<input
        type="date"
        bind:value={to}
        onchange={resetPage}
      /></label
    ><button class="text-button" onclick={clearDates} disabled={!from && !to}
      >Clear dates</button
    >
  </div>
  <p class="filter-context">
    Filter by registration date. Both dates are included.{#if from || to}
      Declarations without a registration date are excluded.{:else}
      Declarations without a registration date appear last.{/if}
  </p>
  {#if reversed}<p class="coverage-note" role="alert">
      The start date must be on or before the end date.
    </p>
  {:else if filtered.length === 0}<p class="empty-details">
      {details.declarations.length === 0
        ? "No declarations are stored for this MP."
        : "No declarations match these dates. Clear or change the dates."}
    </p>
  {:else}<p class="history-result-count">
      Showing {(page - 1) * pageSize + 1} to {Math.min(
        page * pageSize,
        filtered.length,
      )} of {filtered.length} declarations
    </p>
    <MemberDeclarations declarations={visible} />
    <nav class="history-pagination" aria-label="Declaration pages">
      <button
        class="text-button"
        disabled={page === 1}
        onclick={() => (page -= 1)}>Previous</button
      ><span>Page {page} of {pageCount}</span><button
        class="text-button"
        disabled={page === pageCount}
        onclick={() => (page += 1)}>Next</button
      >
    </nav>
  {/if}
</section>
import { registrationTimeline } from "../src/lib/registration-timeline";
import { expect, test } from "@playwright/test";
import { summarizeMember, formatPounds } from "../src/lib/member-summary";
import {
  categoryBars,
  type MemberDetails,
  type MemberDeclaration,
  type FundingEntry,
} from "../src/lib/entity-details";

function entry(
  amount: string | null,
  currency: string | null = "GBP",
): FundingEntry {
  return { amount, currency, funder: null, paymentType: null };
}
function declaration(
  registeredAt: string | null,
  entries: FundingEntry[],
  categoryName = "Employment and earnings",
  categoryId = 12,
): MemberDeclaration {
  return { registeredAt, entries, categoryName, categoryId, sourceId: 1 };
}
function details(declarations: MemberDeclaration[]): MemberDetails {
  return {
    member: {
      id: "1",
      name: "Example",
      partyName: "",
      membershipFrom: "",
      isCurrentCommons: true,
    },
    declarations,
    summary: {
      currencies: [
        {
          currency: "EUR",
          amount: "999",
          categories: [],
          entryCount: 1,
          unknownAmountCount: 0,
        },
        {
          currency: "GBP",
          amount: "123.45",
          categories: [],
          entryCount: 1,
          unknownAmountCount: 0,
        },
      ],
      entryCount: 1,
      unknownCurrencyCount: 0,
      firstRegisteredAt: null,
      lastRegisteredAt: null,
      undatedDeclarationCount: 0,
    },
  };
}

test("summary preserves duplicate arbitrary precision values and server pounds total", () => {
  const summary = summarizeMember(
    details([
      declaration("2026-01-05T00:00:00Z", [
        entry("9007199254740993.123456789"),
        entry("9007199254740993.123456789"),
        entry("0.000000001"),
      ]),
      declaration("2026-01-31T23:59:59Z", [entry("-0.000000001")]),
    ]),
  );
  expect(summary.total).toBe("123.45");
  expect(summary.earnings).toEqual([
    {
      start: "2026-01-01",
      amount: "18014398509481986.246913578",
      incomplete: false,
    },
  ]);
  expect(formatPounds(summary.earnings[0].amount)).toBe(
    "£18,014,398,509,481,986.246913578",
  );
  expect(formatPounds("-5")).toBe("−£5.00");
  expect(formatPounds(null)).toBe("Amount unavailable");
});

test("UTC registration months preserve negatives, zero, gaps and incomplete values", () => {
  const summary = summarizeMember(
    details([
      declaration("2025-12-31T23:00:00-02:00", [entry("-2.5")]),
      declaration("2025-12-01T00:30:00+02:00", [entry("0"), entry(null)]),
      declaration("2025-12-20T00:00:00Z", [entry("-5")]),
      declaration("2026-01-19T00:00:00Z", [entry("4"), entry("900", null)]),
      declaration("2026-03-26T00:00:00Z", [entry(null)]),
      declaration(null, [entry("88")]),
      declaration("2027-01-01T00:00:00Z", [entry("77", "EUR")]),
    ]),
  );
  expect(summary.earnings).toEqual([
    { start: "2025-11-01", amount: "0", incomplete: true },
    { start: "2025-12-01", amount: "-5", incomplete: false },
    { start: "2026-01-01", amount: "1.5", incomplete: true },
    { start: "2026-02-01", amount: "0", incomplete: false },
    { start: "2026-03-01", amount: null, incomplete: true },
  ]);
  expect(summary.undated).toBe(true);
});

test("month iteration includes leap February after a January 31 registration", () => {
  expect(
    registrationTimeline([
      declaration("2024-01-31T23:59:59Z", [entry("1")]),
      declaration("2024-02-29T00:00:00Z", [entry("2")]),
      declaration("2024-03-31T23:59:59Z", [entry("3")]),
    ]),
  ).toEqual({
    months: [
      { start: "2024-01-01", amount: "1", incomplete: false },
      { start: "2024-02-01", amount: "2", incomplete: false },
      { start: "2024-03-01", amount: "3", incomplete: false },
    ],
    undated: false,
  });
});

test("earnings labels own classification across legacy IDs and current label variants", () => {
  const summary = summarizeMember(
    details([
      declaration("2026-01-05Z", [entry("1")], "Employment and earnings", 12),
      declaration(
        "2026-01-05Z",
        [entry("2")],
        "Employment and earnings - Ad hoc payments",
        99,
      ),
      declaration(
        "2026-01-05Z",
        [entry("3")],
        "Employment and earnings - Ongoing paid employment",
        2,
      ),
      declaration("2026-01-05Z", [entry("4")], "Employment", 1),
      declaration("2026-01-05Z", [entry("100")], "Gifts", 1),
    ]),
  );
  expect(summary.earnings[0].amount).toBe("10");
  expect(summarizeMember(details([])).earnings).toEqual([]);
  const undated = summarizeMember(details([declaration(null, [entry("3")])]));
  expect(undated.earnings).toEqual([]);
  expect(undated.undated).toBe(true);
  expect(
    summarizeMember(details([declaration("2026-01-05Z", [entry("0")])]))
      .earnings[0].amount,
  ).toBe("0");
});

test("category shares preserve decimal magnitudes without cancellation", () => {
  const amounts = ["0.08", "-0.0200", "0", "-0.00", null];
  expect(
    categoryBars(
      amounts.map((amount) => ({ amount })),
      "total",
    ),
  ).toEqual([
    { width: 80, negative: false },
    { width: 20, negative: true },
    { width: 0, negative: false },
    { width: 0, negative: false },
    { width: 0, negative: false },
  ]);
  expect(categoryBars([{ amount: "5" }, { amount: "-5" }], "total")).toEqual([
    { width: 50, negative: false },
    { width: 50, negative: true },
  ]);
  const thirds = categoryBars(
    Array.from({ length: 3 }, () => ({ amount: "1" })),
    "total",
  );
  for (const bar of thirds) expect(bar.width).toBeCloseTo(100 / 3, 7);
  expect(thirds.reduce((sum, bar) => sum + bar.width, 0)).toBeCloseTo(100, 7);
});

test("empty and unavailable amounts have no bar for either basis", () => {
  for (const basis of ["total", "maximum"] satisfies ("total" | "maximum")[]) {
    expect(categoryBars([], basis)).toEqual([]);
    expect(
      categoryBars(
        [{ amount: null }, { amount: "0" }, { amount: "-0.00" }],
        basis,
      ),
    ).toEqual([
      { width: 0, negative: false },
      { width: 0, negative: false },
      { width: 0, negative: false },
    ]);
  }
});

test("category ratios remain finite beyond Number precision and range", () => {
  const huge = "9".repeat(400);
  expect(categoryBars([{ amount: huge }, { amount: huge }], "total")).toEqual([
    { width: 50, negative: false },
    { width: 50, negative: false },
  ]);
  expect(
    categoryBars(
      [
        { amount: "9007199254740993.123456789" },
        { amount: "27021597764222979.370370367" },
      ],
      "total",
    ),
  ).toEqual([
    { width: 25, negative: false },
    { width: 75, negative: false },
  ]);
});

test("weekly bars retain maximum scaling and hundredth-percent truncation", () => {
  expect(
    categoryBars(
      [
        { amount: "3" },
        { amount: "-1" },
        { amount: "0.0001" },
        { amount: null },
      ],
      "maximum",
    ),
  ).toEqual([
    { width: 100, negative: false },
    { width: 33.33, negative: true },
    { width: 0, negative: false },
    { width: 0, negative: false },
  ]);
  const weeks = Array.from({ length: 200 }, () => ({ amount: "1" }));
  expect(categoryBars(weeks, "maximum").every((bar) => bar.width === 100)).toBe(
    true,
  );
});

test("funding timeline includes every category with exact UTC months and missing coverage", () => {
  const timeline = registrationTimeline([
    declaration(
      "2026-01-04T23:59:59Z",
      [entry("9007199254740993.123456789")],
      "Gifts",
    ),
    declaration(
      "2026-01-05T00:00:00Z",
      [entry("-2.5"), entry("0.5"), entry(null), entry("900", null)],
      "Donations",
    ),
    declaration("2026-03-19T00:00:00Z", [entry(null)], "Visits"),
    declaration(null, [entry("5")], "Gifts"),
    declaration("2027-01-01T00:00:00Z", [entry("99", "EUR")], "Gifts"),
  ]);
  expect(timeline).toEqual({
    undated: true,
    months: [
      {
        start: "2026-01-01",
        amount: "9007199254740991.123456789",
        incomplete: true,
      },
      { start: "2026-02-01", amount: "0", incomplete: false },
      { start: "2026-03-01", amount: null, incomplete: true },
    ],
  });
  expect(
    registrationTimeline([declaration(null, [entry("99", "EUR")])]),
  ).toEqual({ months: [], undated: false });
});
